import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  const resources = [];
  const timelines = [];
  const primitiveResults = [];

  root.userData.handlers = {};

  const backdropGeometry = new THREE.PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.910, 0.925, 0.949),
      smoothstep(0.58, 1.0, uv().y)
    ),
    smoothstep(0.0, 0.82, uv().y)
  );

  const backdrop = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const surfaceGeometry = new THREE.PlaneGeometry(4.8, 1.28);
  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: 0x16161d,
    transparent: true,
    opacity: 0.96
  });
  const surface = new THREE.Mesh(surfaceGeometry, surfaceMaterial);
  surface.position.set(0, 0, -0.35);
  root.add(surface);
  resources.push(surfaceGeometry, surfaceMaterial);

  const edgeGeometry = new THREE.PlaneGeometry(4.8, 0.025);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: 0xff2a38
  });
  const edge = new THREE.Mesh(edgeGeometry, edgeMaterial);
  edge.position.set(0, -0.64, -0.28);
  root.add(edge);
  resources.push(edgeGeometry, edgeMaterial);

  const accentGeometry = new THREE.PlaneGeometry(0.7, 0.08);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: 0xe8ecf2
  });
  const accent = new THREE.Mesh(accentGeometry, accentMaterial);
  accent.position.set(-1.72, 0.42, -0.16);
  root.add(accent);
  resources.push(accentGeometry, accentMaterial);

  const foregroundGeometry = new THREE.PlaneGeometry(1.15, 0.34);
  const foregroundMaterial = new MeshBasicNodeMaterial({
    color: 0x0b0b10,
    transparent: true,
    opacity: 0.82
  });
  const foreground = new THREE.Mesh(foregroundGeometry, foregroundMaterial);
  foreground.position.set(1.55, -0.28, 0.08);
  root.add(foreground);
  resources.push(foregroundGeometry, foregroundMaterial);

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (root.userData.cleaned) {
        texture.dispose?.();
        return;
      }

      surfaceMaterial.map = texture;
      surfaceMaterial.transparent = true;
      surfaceMaterial.needsUpdate = true;
      resources.push(texture);
    }).catch(() => {});
  }

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler === 'function') {
      const result = handler(root, primitive.params);
      if (result) {
        primitiveResults.push(result);
        if (result.timeline) timelines.push(result.timeline);
      }
    }
  }

  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const result of primitiveResults) {
      result?.cleanup?.();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.clear();
  };

  return root;
}

export default createNode;
